import { field, textarea, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "swCacheName", label: "Cache name", value: "v1" })}${select({ id: "swStrategy", label: "Default strategy", options: [{label:"Cache-first (static assets)",value:"cache-first"},{label:"Network-first (API/data)",value:"network-first"},{label:"Stale-while-revalidate (balanced)",value:"swr"},{label:"Network-only",value:"network-only"},{label:"Cache-only",value:"cache-only"}], value: "swr" })}</div><div class="field-grid">${textarea({ id: "swPrecache", label: "Precache URLs (one per line)", value: "/\n/styles.css\n/main.js\n/offline.html", full: true })}</div><div class="field-grid">${checkbox({ id: "swOffline", label: "Include offline fallback page", checked: true })}${field({ id: "swOfflinePage", label: "Offline page URL", value: "/offline.html" })}</div><div class="field-grid">${checkbox({ id: "swModule", label: "Use ES module syntax (importScripts alternative)", checked: true })}${checkbox({ id: "swSkipWaiting", label: "Auto-activate (skipWaiting + clients.claim)", checked: true })}</div>`,generate(root) {const cacheName = root.querySelector("#swCacheName").value.trim() || "v1";const strategy = root.querySelector("#swStrategy").value;const precacheRaw = root.querySelector("#swPrecache").value.trim();const precacheUrls = precacheRaw ? precacheRaw.split("\n").filter(Boolean).map(u => ` '${u.trim()}'`) : [" '/'"];const hasOffline = root.querySelector("#swOffline").checked;const offlinePage = root.querySelector("#swOfflinePage").value.trim() || "/offline.html";const useModule = root.querySelector("#swModule").checked;const skipWaiting = root.querySelector("#swSkipWaiting").checked;const lines = [];lines.push("// Service Worker — ES Module Template");lines.push("// Baseline 2026: Chrome 91+, Edge 91+, Safari 15.4+, Firefox 119+");lines.push(`// Register with: navigator.serviceWorker.register('/sw.js', { type: '${useModule ? "module" : "classic"}' })`);lines.push("");lines.push("const CACHE_NAME = '" + cacheName + "';");lines.push("const PRECACHE_URLS = [");lines.push(precacheUrls.join(",\n"));lines.push("];");lines.push("");lines.push("// Install — precache static assets");lines.push("self.addEventListener('install', (event) => {");if (skipWaiting) lines.push(" self.skipWaiting();");lines.push(" event.waitUntil(");lines.push(" caches.open(CACHE_NAME).then((cache) => cache.addAll(PRECACHE_URLS))");lines.push(" );");lines.push("});");lines.push("");lines.push("// Activate — clean old caches");lines.push("self.addEventListener('activate', (event) => {");if (skipWaiting) lines.push(" clients.claim();");lines.push(" event.waitUntil(");lines.push(" caches.keys().then((keys) =>");lines.push(" Promise.all(keys.map((key) => key !== CACHE_NAME ? caches.delete(key) : null))");lines.push(" )");lines.push(" );");lines.push("});");lines.push("");lines.push("// Fetch — strategy: " + strategy);lines.push("self.addEventListener('fetch', (event) => {");lines.push(" const { request } = event;");lines.push("");lines.push(" // Skip non-GET requests");lines.push(" if (request.method !== 'GET') return;");lines.push("");const strategyCode = {"cache-first": [" event.respondWith("," caches.match(request).then((cached) => {"," return cached || fetch(request).then((response) => {"," return caches.open(CACHE_NAME).then((cache) => {"," cache.put(request, response.clone());"," return response;"," });"," });"," })"," );"],"network-first": [" event.respondWith("," fetch(request).then((response) => {"," return caches.open(CACHE_NAME).then((cache) => {"," cache.put(request, response.clone());"," return response;"," });"," }).catch(() => caches.match(request))"," );"],"swr": [" event.respondWith("," caches.match(request).then((cached) => {"," const fetchPromise = fetch(request).then((response) => {"," caches.open(CACHE_NAME).then((cache) => cache.put(request, response.clone()));"," return response;"," });"," return cached || fetchPromise;"," })"," );"],"network-only": [" event.respondWith(fetch(request));"],"cache-only": [" event.respondWith("," caches.match(request).then((cached) => cached || new Response('Not cached', { status: 404 }))"," );"]};lines.push(...strategyCode[strategy]);lines.push("});");lines.push("");if (hasOffline) {lines.push("// Offline fallback");lines.push("self.addEventListener('fetch', (event) => {");lines.push(" event.respondWith(");lines.push(" fetch(event.request).catch(() => caches.match('" + offlinePage + "'))");lines.push(" );");lines.push("});");}return { output: lines.join("\n"), preview: "" };}};